using D2NG.Core.ItemData;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace D2NG.Core.SkillData;

/// <summary>
/// The skills of the game's compiled table. Generated by the MpqData tool for damage calculations
/// outside the bot; nothing loads it at runtime.
/// </summary>
public sealed class SkillTable
{
    public List<ItemAffixSourceFile> Sources { get; set; } = [];
    public List<SkillEntry> Skills { get; set; } = [];

    public static SkillTable Load(string path)
        => JsonSerializer.Deserialize<SkillTable>(File.ReadAllText(path), SerializerOptions);

    public void Save(string path) => File.WriteAllText(path, JsonSerializer.Serialize(this, SerializerOptions));

    private static readonly JsonSerializerOptions SerializerOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter() }
    };
}
